#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* write position */
    size_t tail;  /* read position */
    size_t count; /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t free_space = rb->capacity - rb->count;
    size_t wrote = 0;

    if (len > free_space)
        wrote = free_space;
    else
        wrote = len;

    /* How many bytes fit from head to end of buffer */
    size_t tail_to_end = rb->capacity - rb->head;

    if (wrote <= tail_to_end) {
        memcpy(rb->buf + rb->head, data, wrote);
        rb->head += wrote;
        /* Wrap around is implicit when later writes hit the end */
    } else {
        /* Write first batch to head->end */
        memcpy(rb->buf + rb->head, data, tail_to_end);

        /* Remaining goes at start of buffer if there's room */
        size_t remaining = wrote - tail_to_end;
        if (remaining > 0)
            if (rb->capacity == rb->count) {
                /* full circular write not possible, clamp to fit */
                rb->head = remaining;
            } else {
                memcpy(rb->buf, data + tail_to_end, remaining);
                rb->head = remaining;
        }
    }

    rb->count += wrote;
    return wrote;
}

